export const readerMetas=readers.map(r=>r.meta);
export const readerAliases=readers.flatMap(r=>r.aliases);
export function canonicalReaderSlug(slug){return reviewedNavigation[slug]?.slug||readers.find(r=>r.meta.slug===slug||r.aliases.includes(slug))?.meta.slug||slug;}
export function renderDenseReader(slug,link){return readers.find(r=>r.meta.slug===canonicalReaderSlug(slug))?.render(link)||null;}
export function mountDenseReaders(scope=document){for(const r of readers)r.mount(scope);for(const article of scope.querySelectorAll('[data-dense-moe],[data-dense-attention],[data-dense-topic]'))mountScrollRegions(article);}
export function disposeDenseReaders(scope=document){for(const article of scope.querySelectorAll('[data-dense-moe],[data-dense-attention],[data-dense-topic]'))article.dispatchEvent(new Event('atlas-reader-dispose'));}
